<!doctype html><html lang="pt-BR"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Catálogo de livros</title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css" rel="stylesheet"></head><body class="container py-5">
<header class="d-flex justify-content-between align-items-center flex-wrap gap-3 mb-4"><h1>Catálogo de livros</h1><nav class="d-flex gap-2 align-items-center">
<?php if (Auth::usuario()): ?><?php if (!empty(Auth::usuario()['foto'])): ?><img src="<?= htmlspecialchars(Auth::usuario()['foto'],ENT_QUOTES,'UTF-8') ?>" alt="Foto de perfil" width="40" height="40" style="object-fit:cover;border-radius:50%"> <?php endif; ?><span>Olá, <?= htmlspecialchars(Auth::usuario()['nome'],ENT_QUOTES,'UTF-8') ?> (<?= Auth::admin()?'administrador':'cliente' ?>)</span><form method="post" action="index.php?acao=sair"><input type="hidden" name="csrf" value="<?= htmlspecialchars($_SESSION['csrf'],ENT_QUOTES,'UTF-8') ?>"><button class="btn btn-outline-secondary">Sair</button></form><?php else: ?><a class="btn btn-outline-primary" href="index.php?acao=login">Entrar</a><a class="btn btn-primary" href="index.php?acao=cadastro">Cadastrar</a><?php endif; ?></nav></header>
<?php if (Auth::admin()): ?><a href="index.php?acao=novo" class="btn btn-success mb-3">Novo livro</a><?php endif; ?>
<div class="table-responsive"><table class="table table-striped align-middle"><thead><tr><th>ID</th><th>ISBN</th><th>Título</th><th>Autor</th><th>Preço</th><th>Estoque</th><th>Status</th><th>Categorias</th><?php if (Auth::admin()): ?><th>Ações</th><?php endif; ?></tr></thead><tbody>
<?php foreach ($livros as $l): ?><tr><td><?= (int)$l['id'] ?></td><td><?= htmlspecialchars($l['isbn'],ENT_QUOTES,'UTF-8') ?></td><td><?= htmlspecialchars($l['titulo'],ENT_QUOTES,'UTF-8') ?></td><td><?= htmlspecialchars((string)$l['autor'],ENT_QUOTES,'UTF-8') ?></td><td>R$ <?= number_format((float)$l['preco'],2,',','.') ?></td><td><?= (int)$l['estoque'] ?></td><td><?= htmlspecialchars($l['status'],ENT_QUOTES,'UTF-8') ?></td><td><?= htmlspecialchars($l['categorias_nomes']??'',ENT_QUOTES,'UTF-8') ?></td>
<?php if (Auth::admin()): ?><td><div class="d-flex gap-2"><a class="btn btn-sm btn-primary" href="index.php?acao=editar&id=<?= (int)$l['id'] ?>">Editar</a><form method="post" action="index.php?acao=deletar" onsubmit="return confirm('Excluir este livro?')"><input type="hidden" name="csrf" value="<?= htmlspecialchars($_SESSION['csrf'],ENT_QUOTES,'UTF-8') ?>"><input type="hidden" name="id" value="<?= (int)$l['id'] ?>"><button class="btn btn-sm btn-danger">Excluir</button></form></div></td><?php endif; ?></tr><?php endforeach; ?>
</tbody></table></div></body></html>
